## Operations Without Modifying Types

```xiom
// The AST node types (the 'elements')
pub enum Expr {
  Number(value: Int),
  Add(left: Box[Expr], right: Box[Expr]),
  Multiply(left: Box[Expr], right: Box[Expr]),
}

// The Visitor interface
pub interface ExprVisitor[T] {
  fn visit_number(self: &Self, value: Int) -> T;
  fn visit_add(self: &Self, left: &Expr, right: &Expr) -> T;
  fn visit_multiply(self: &Self, left: &Expr, right: &Expr) -> T;
}

// The accept method (one per type)
impl Expr {
  fn accept[T](self: &Expr, visitor: &dyn ExprVisitor[T]) -> T {
    return match self {
      Expr::Number(v) => visitor.visit_number(v),
      Expr::Add(l, r) => visitor.visit_add(l, r),
      Expr::Multiply(l, r) => visitor.visit_multiply(l, r),
    };
  }
}

// Implementing a concrete visitor
pub type Evaluator = {};
impl ExprVisitor[Int] for Evaluator {
  fn visit_number(self: &Evaluator, value: Int) -> Int { return value; }
  fn visit_add(self: &Evaluator, left: &Expr, right: &Expr) -> Int {
    return left.accept(self) + right.accept(self);
  }
  fn visit_multiply(self: &Evaluator, left: &Expr, right: &Expr) -> Int {
    return left.accept(self) * right.accept(self);
  }
}

fn main() {
  // (1 + 2) * 3
  let expr = Expr::Multiply(
    Box::new(Expr::Add(Box::new(Expr::Number(1)), Box::new(Expr::Number(2)))),
    Box::new(Expr::Number(3)),
  );
  let evaluator = Evaluator{};
  let result = expr.accept(&evaluator);  // 9
}
```

### Adding New Operations

```xiom
// New visitor: pretty printer — NO changes to Expr types!
pub type PrettyPrinter = {};
impl ExprVisitor[Str] for PrettyPrinter {
  fn visit_number(self: &PrettyPrinter, value: Int) -> Str { return value.to_str(); }
  fn visit_add(self: &PrettyPrinter, left: &Expr, right: &Expr) -> Str {
    return "(" + left.accept(self) + " + " + right.accept(self) + ")";
  }
  fn visit_multiply(self: &PrettyPrinter, left: &Expr, right: &Expr) -> Str {
    return "(" + left.accept(self) + " * " + right.accept(self) + ")";
  }
}

let pretty = expr.accept(&PrettyPrinter{});  // "((1 + 2) * 3)"
```

### When to Use Visitor

- Stable type hierarchy, frequently added operations
- Compilers: AST nodes + many passes (type check, optimize, codegen)
- Document processing: nodes + many exporters (HTML, PDF, Markdown)
- UI frameworks: widget tree + renderers

