pub enum Shape {
  Circle(radius: Float64),
  Rectangle(width: Float64, height: Float64),
}

pub interface ShapeVisitor[T] {
  fn visit_circle(self: &Self, radius: Float64) -> T;
  fn visit_rectangle(self: &Self, width: Float64, height: Float64) -> T;
}

pub type AreaCalc = {};
impl ShapeVisitor[Float64] for AreaCalc {
  fn visit_circle(self: &AreaCalc, r: Float64) -> Float64 { return 3.14159 * r * r; }
  fn visit_rectangle(self: &AreaCalc, w: Float64, h: Float64) -> Float64 { return w * h; }
}

fn main() -> Int {
  let circle_area = 3.14159 * 5.0 * 5.0;
  let rect_area = 4.0 * 6.0;
  return (circle_area + rect_area) as Int;
}
